package io.coolbox.decisiontree;
import io.coolbox.internal.*;import com.sun.jna.ptr.IntByReference;
/** Bagged classifier (Python: {@code decision_tree.RandomForest}). */
public final class RandomForest extends NativeHandle {private static final TreeNative N=TreeNative.INSTANCE;private int features;public RandomForest(int numTrees,int maxDepth){super(N.coolbox_trees_random_forest_new(numTrees,maxDepth),N::coolbox_trees_random_forest_free);}public RandomForest fit(int[][] x,int[] y){int c=DecisionTree.columns(x);if(y.length!=x.length)throw new IllegalArgumentException("label count differs from row count");ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_trees_random_forest_fit(handle(),DecisionTree.flatten(x),x.length,c,y,e.pointer(),e.capacity()));features=c;return this;}public int predict(int[] sample){if(sample.length!=features)throw new IllegalArgumentException("sample feature count must match fitted model");IntByReference o=new IntByReference();ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_trees_random_forest_predict(handle(),sample,sample.length,o,e.pointer(),e.capacity()));return o.getValue();}}
